def mk(rows):
  out=[]
  for q,c,ds,p in rows:
    o=list(ds); o.insert(p,c); assert len(set(o))==len(o),o; out.append([q,o])
  return out
def unit(n,one,many,acc):
  # ar number + unit word with agreement for given cases
  if 3<=n<=10: return f'{ar(n)} {many}'
  if n%100>=11 and n%100<=99 or (11<=n<=99): return f'{ar(n)} {acc}'
  return f'{ar(n)} {one}'
